const BIBLE_LIVRES_AT = {
"gen": { "auteur": "La tradition juive et chrétienne attribue tout le Pentateuque, donc la Genèse, à Moïse. Le livre lui-même ne donne pas de nom d'auteur.", "specialistes": "La majorité des spécialistes pensent que le livre a été écrit par plusieurs auteurs et éditeurs, bien plus tard que Moïse. Beaucoup le placent après l'exil à Babylone.", "date": "Les spécialistes proposent une rédaction finale après l'exil, peut-être au Ve siècle avant Jésus-Christ. Si Moïse en était l'auteur, ce serait vers le XIIIe siècle avant Jésus-Christ. Ces dates sont discutées.", "genre": "Récits des origines et histoire d'une famille, avec une grande part de langage symbolique.", "lieu": "Le lieu exact est inconnu. Le texte a pris sa forme finale après l'exil à Babylone.", "resume": "Le livre raconte la création du monde, Adam et Ève, Noé et le déluge. Puis il suit Abraham, Isaac, Jacob et Joseph, jusqu'à l'arrivée de la famille d'Israël en Égypte.", "message": "Dieu crée un monde bon, et il ne lâche pas l'humanité malgré ses fautes. Il choisit Abraham pour bénir toutes les familles de la terre.", "personnes": [ { "nom": "Adam et Ève", "qui": "Le premier homme et la première femme dans le récit de la création." }, { "nom": "Noé", "qui": "Un homme juste que Dieu sauve avec sa famille au moment du déluge." }, { "nom": "Abraham", "qui": "Le père des croyants, à qui Dieu promet une grande descendance et une terre." }, { "nom": "Jacob", "qui": "Petit-fils d'Abraham, il reçoit le nom d'Israël, et ses douze fils donneront les douze tribus." }, { "nom": "Joseph", "qui": "Fils de Jacob, vendu par ses frères, il devient un grand responsable en Égypte." } ], "alire": "Commencez par les chapitres 1 à 3, puis l'histoire d'Abraham à partir du chapitre 12, et gardez le chapitre 37 et suivants pour Joseph.", "sources": [ "Wikipédia en anglais, article « Book of Genesis »" ] },
"exo": { "auteur": "La tradition attribue l'Exode à Moïse. Le livre ne signe pas son texte.", "specialistes": "La majorité des spécialistes voient dans l'Exode une œuvre composée à partir de traditions orales et écrites plus anciennes. La plupart des historiens ne tiennent pas le récit pour une histoire exacte, car l'archéologie n'a pas trouvé de traces claires.", "date": "Une première rédaction pendant l'exil à Babylone (VIe siècle avant Jésus-Christ), puis des retouches à l'époque perse (Ve siècle). Ces dates sont approximatives.", "genre": "Récit de libération mêlé de lois et de consignes pour le culte.", "lieu": "Le récit se passe en Égypte, dans le désert et au mont Sinaï. Le lieu de rédaction est inconnu.", "resume": "Dieu libère le peuple d'Israël de l'esclavage en Égypte grâce à Moïse. Le peuple traverse la mer, arrive au mont Sinaï et reçoit les dix commandements. Dieu fait alliance avec lui.", "message": "Dieu entend le cri de ceux qui souffrent et il libère. Il propose ensuite une alliance, c'est-à-dire un lien de confiance.", "personnes": [ { "nom": "Moïse", "qui": "Choisi par Dieu pour conduire le peuple hors d'Égypte et recevoir la loi." }, { "nom": "Aaron", "qui": "Le frère de Moïse, qui l'aide et devient prêtre." }, { "nom": "Pharaon", "qui": "Le roi d'Égypte qui refuse d'abord de laisser partir les Hébreux." }, { "nom": "Le peuple d'Israël", "qui": "Les descendants de Jacob, esclaves en Égypte puis libérés." } ], "alire": "Lisez les chapitres 1 à 15, le récit de la libération, puis les dix commandements au chapitre 20. Les chapitres de plans du sanctuaire peuvent attendre.", "sources": [ "Wikipédia en anglais, article « Book of Exodus »" ] },
"lev": { "auteur": "La tradition attribue le Lévitique à Moïse, car presque tout le livre est présenté comme des paroles de Dieu à Moïse.", "specialistes": "Les spécialistes y voient un livre lentement construit, surtout par des milieux de prêtres. Il aurait pris sa forme actuelle à l'époque perse, ce qui reste discuté.", "date": "Forme finale probablement entre 538 et 332 avant Jésus-Christ, mais la date est discutée.", "genre": "Loi et règles pour le culte et la vie du peuple.", "lieu": "Le récit se situe au pied du mont Sinaï. Le lieu d'écriture est inconnu.", "resume": "Le livre explique comment offrir des sacrifices et comment les prêtres, Aaron et ses fils, servent dans la tente du sanctuaire. Il donne aussi des règles de pureté et de vie quotidienne.", "message": "Dieu veut habiter au milieu de son peuple. Pour cela, les rites aident à demander pardon et à rester proche de lui.", "personnes": [ { "nom": "Moïse", "qui": "Il reçoit de Dieu les paroles et les transmet au peuple." }, { "nom": "Aaron et ses fils", "qui": "Les premiers prêtres, chargés des offrandes dans le sanctuaire." }, { "nom": "Les Lévites", "qui": "La tribu de Lévi, mise au service du culte." } ], "alire": "Ce livre est difficile. Lisez surtout le chapitre 19, qui parle de l'amour du prochain, et le chapitre 16 sur le jour du pardon.", "sources": [ "Wikipédia en anglais, article « Book of Leviticus »" ] },
"num": { "auteur": "La tradition attribue les Nombres à Moïse.", "specialistes": "La majorité des spécialistes pensent que le Pentateuque a pris sa forme actuelle après l'exil, à partir de textes et de récits plus anciens écrits par plusieurs mains.", "date": "Forme finale après l'exil, donc après 520 avant Jésus-Christ environ. Des versets du livre figurent sur de petits rouleaux d'argent datés de la fin du VIIe siècle ou du début du VIe siècle avant Jésus-Christ.", "genre": "Récit de marche dans le désert, avec des listes et des lois.", "lieu": "Le récit va du mont Sinaï jusqu'aux portes de Canaan, en passant par le désert. Le lieu d'écriture est inconnu.", "resume": "Le peuple est compté, puis se remet en route depuis le Sinaï. Il se plaint souvent, hésite devant la Terre promise et doit errer longtemps dans le désert avant d'arriver à ses frontières.", "message": "Dieu reste fidèle à son peuple malgré ses plaintes et ses peurs.", "personnes": [ { "nom": "Moïse", "qui": "Le guide du peuple, souvent fatigué par les plaintes." }, { "nom": "Aaron", "qui": "Le grand prêtre, frère de Moïse." }, { "nom": "Les douze explorateurs", "qui": "Des hommes envoyés voir la terre de Canaan avant d'y entrer." }, { "nom": "Le peuple d'Israël", "qui": "Il avance dans le désert, entre confiance et découragement." } ], "alire": "Lisez le chapitre 6 avec la belle bénédiction, puis les chapitres 11 à 14 sur les plaintes et les explorateurs.", "sources": [ "Wikipédia en anglais, article « Book of Numbers »" ] },
"deu": { "auteur": "La tradition juive croit que Dieu a dicté la loi à Moïse, et que le livre vient de lui. Il a même été fixé comme principe de foi au Moyen Âge.", "specialistes": "Presque tous les spécialistes refusent l'idée que Moïse soit l'auteur. Ils voient un livre écrit par plusieurs milieux, avec une base de lois ancienne et des ajouts ensuite.", "date": "Les spécialistes le placent entre le VIIe et le Ve siècle avant Jésus-Christ, souvent à l'époque du roi Josias. C'est approximatif.", "genre": "Grands discours et lois, à la manière d'un testament.", "lieu": "Le récit se passe dans les plaines de Moab, avant l'entrée en Terre promise. Le lieu de rédaction est probablement le royaume de Juda, mais ce n'est pas certain.", "resume": "Moïse parle une dernière fois au peuple avant de mourir. Il rappelle ce que Dieu a fait, répète la loi et invite à rester fidèle. Le livre se termine par sa mort.", "message": "Dieu invite à choisir la vie en l'aimant de tout son cœur.", "personnes": [ { "nom": "Moïse", "qui": "Il prononce ses derniers discours." }, { "nom": "Josué", "qui": "Le successeur choisi pour conduire le peuple." }, { "nom": "Le peuple d'Israël", "qui": "Il s'apprête à entrer dans la Terre promise." } ], "alire": "Commencez par le chapitre 6, la prière « Écoute, Israël », puis le chapitre 30 sur le choix de la vie.", "sources": [ "Wikipédia en anglais, article « Deuteronomy »" ] },
"jos": { "auteur": "Le Talmud de Babylone, écrit entre le IIIe et le Ve siècle après Jésus-Christ, attribue le livre à Josué lui-même. Le livre est pourtant anonyme.", "specialistes": "Les spécialistes pensent qu'il a été écrit bien après Josué, comme une partie d'une grande histoire appelée l'histoire deutéronomiste, qui va du Deutéronome aux Rois.", "date": "Une première version vers la fin du règne du roi Josias (VIIe siècle avant Jésus-Christ), terminée après la chute de Jérusalem en 586, peut-être même après 539 avant Jésus-Christ.", "genre": "Récit historique et théologique, avec des listes de territoires.", "lieu": "Le récit se passe en Canaan, de Jéricho aux collines du pays. Le lieu de rédaction est inconnu.", "resume": "Après Moïse, Josué conduit le peuple à travers le Jourdain. Le récit raconte la prise de Jéricho et le partage du pays entre les tribus. Il se termine par l'adieu de Josué.", "message": "Dieu tient ses promesses, et chacun doit choisir qui il veut servir.", "personnes": [ { "nom": "Josué", "qui": "Le successeur de Moïse, chef du peuple." }, { "nom": "Rahab", "qui": "Une femme de Jéricho qui protège les messagers d'Israël." }, { "nom": "Les douze tribus", "qui": "Les groupes du peuple d'Israël qui reçoivent chacun une part du pays." } ], "alire": "Lisez les chapitres 1 à 6 pour l'entrée dans le pays, puis le chapitre 24 pour la grande alliance de Sichem. Un avertissement honnête, certains récits de guerre sont très violents.", "sources": [ "Wikipédia en anglais, article « Book of Joshua »" ] },
"jdg": { "auteur": "Le livre ne nomme pas son auteur. Plusieurs auteurs anonymes y ont travaillé.", "specialistes": "Les spécialistes y voient une collection d'anciennes histoires de héros de tribus, reprise et mise en forme plus tard par les auteurs de l'histoire deutéronomiste. Beaucoup pensent que ces récits ne sont pas de l'histoire exacte.", "date": "Des récits plus anciens, une mise en forme finale probablement au VIe siècle avant Jésus-Christ, à l'époque de l'exil. Ces dates sont discutées.", "genre": "Récits de héros et histoire racontée avec une leçon.", "lieu": "Le récit se passe dans le pays de Canaan. Le lieu d'écriture est inconnu.", "resume": "Après Josué, le peuple oublie Dieu, subit l'oppression, appelle au secours, et Dieu envoie un « juge » pour le sauver. Ce cycle se répète avec Débora, Gédéon, Samson et d'autres.", "message": "Quand on s'éloigne de Dieu, tout se défait, mais Dieu entend toujours l'appel.", "personnes": [ { "nom": "Débora", "qui": "Une prophétesse et juge qui conduit le peuple à la victoire." }, { "nom": "Gédéon", "qui": "Un juge qui libère le peuple avec une toute petite armée." }, { "nom": "Samson", "qui": "Un juge très fort, célèbre pour ses cheveux longs." }, { "nom": "Jephté", "qui": "Un chef de guerre dont l'histoire est très dure." } ], "alire": "Lisez les chapitres 4 et 5 sur Débora, et 6 à 8 sur Gédéon. Certains récits sont brutaux et font réfléchir.", "sources": [ "Wikipédia en anglais, article « Book of Judges »", "Wikipédia en français, article « Livre des Juges »" ] },
"rut": { "auteur": "La tradition l'attribue au prophète Samuel. Le livre ne nomme pas son auteur.", "specialistes": "Beaucoup de spécialistes pensent que le livre a été écrit plus tard, à l'époque perse, car il insiste sur l'accueil des étrangers. Les avis sont partagés sur la part d'histoire réelle.", "date": "Probablement entre le VIe et le IVe siècle avant Jésus-Christ, à l'époque perse. C'est approximatif.", "genre": "Petit récit, comme une nouvelle.", "lieu": "Le récit se passe à Moab et à Bethléem. Le lieu d'écriture est inconnu.", "resume": "Ruth, une jeune femme de Moab, reste avec sa belle-mère Noémie après la mort de leurs maris. Elles reviennent à Bethléem, où Ruth rencontre Booz et l'épouse. Leur petit-fils sera le roi David.", "message": "Dieu agit dans les petits gestes de fidélité, et il accueille l'étranger.", "personnes": [ { "nom": "Ruth", "qui": "Une jeune femme de Moab qui choisit de suivre sa belle-mère." }, { "nom": "Noémie", "qui": "Sa belle-mère, qui a perdu son mari et ses fils." }, { "nom": "Booz", "qui": "Un homme bon de Bethléem qui épouse Ruth." }, { "nom": "Obed", "qui": "Le fils de Ruth et Booz, grand-père de David." } ], "alire": "Il est court, 4 chapitres. Lisez-le d'une traite, c'est une très bonne porte d'entrée dans l'Ancien Testament.", "sources": [ "Wikipédia en anglais, article « Book of Ruth »" ] },
"1sa": { "auteur": "Selon la tradition juive, Samuel a écrit le livre, avec des ajouts des prophètes Gad et Nathan. À l'origine, 1 et 2 Samuel formaient un seul livre.", "specialistes": "Les spécialistes pensent que le livre a été écrit par plusieurs mains, comme un morceau de l'histoire deutéronomiste, qui aurait pris forme vers le VIIe et le VIe siècle avant Jésus-Christ.", "date": "Rédaction entre environ 630 et 540 avant Jésus-Christ pour l'ensemble de l'histoire deutéronomiste. C'est approximatif et discuté.", "genre": "Récit historique et biographique.", "lieu": "Le récit se passe en Israël, à Silo, Rama, Guibéa et Bethléem. Le lieu de rédaction est inconnu.", "resume": "Le prophète Samuel est appelé enfant par Dieu. Le peuple demande un roi, et Saül devient le premier roi. Puis David, un jeune berger, est choisi et vainc Goliath.", "message": "Dieu regarde le cœur et pas l'apparence.", "personnes": [ { "nom": "Samuel", "qui": "Un prophète appelé par Dieu dès l'enfance, qui choisit les premiers rois." }, { "nom": "Saül", "qui": "Le premier roi d'Israël, qui perd peu à peu la confiance de Dieu." }, { "nom": "David", "qui": "Un jeune berger choisi par Dieu pour devenir roi." }, { "nom": "Goliath", "qui": "Un géant philistin, vaincu par David." } ], "alire": "Lisez le chapitre 3 (l'appel de Samuel) et les chapitres 16 et 17 (David et Goliath).", "sources": [ "Wikipédia en anglais, article « Books of Samuel »", "Wikipédia en français, article « Livres de Samuel »" ] },
"2sa": { "auteur": "Selon la tradition juive, les prophètes Gad et Nathan ont complété l'œuvre commencée par Samuel. 1 et 2 Samuel formaient un seul livre à l'origine.", "specialistes": "Les spécialistes y voient un récit écrit par plusieurs mains, appuyé sur des sources historiques et des récits légendaires, intégré à l'histoire deutéronomiste.", "date": "Rédaction entre environ 630 et 540 avant Jésus-Christ pour l'ensemble de l'histoire deutéronomiste. C'est approximatif.", "genre": "Récit historique et biographique.", "lieu": "Le récit se passe à Hébron et à Jérusalem. Le lieu de rédaction est inconnu.", "resume": "David devient roi de tout Israël et choisit Jérusalem comme capitale. Dieu lui promet une dynastie durable. Puis il commet une faute grave, reconnaît son péché et subit des drames dans sa famille.", "message": "Même un grand roi peut tomber. Dieu pardonne à celui qui se repent, mais les fautes ont des conséquences.", "personnes": [ { "nom": "David", "qui": "Le roi qui unifie le pays et fait de Jérusalem sa capitale." }, { "nom": "Nathan", "qui": "Un prophète qui ose reprocher sa faute à David." }, { "nom": "Bethsabée", "qui": "La femme dont David abuse, mère de Salomon." }, { "nom": "Absalom", "qui": "Un fils de David qui se révolte contre lui." } ], "alire": "Lisez le chapitre 7 sur la promesse faite à David, puis les chapitres 11 et 12 sur sa faute et son repentir.", "sources": [ "Wikipédia en anglais, article « Books of Samuel »", "Wikipédia en français, article « Livres de Samuel »" ] },
"1ki": { "auteur": "Selon la tradition juive, le prophète Jérémie en serait l'auteur. Le livre ne le dit pas.", "specialistes": "La plupart des spécialistes acceptent l'idée d'une grande histoire deutéronomiste, qui s'achève avec les Rois. Elle aurait eu une première édition sous Josias, puis une édition finale au milieu du VIe siècle avant Jésus-Christ.", "date": "Première édition à la fin du VIIe siècle avant Jésus-Christ, édition finale vers le milieu du VIe siècle avant Jésus-Christ. C'est approximatif.", "genre": "Récit historique avec un regard religieux, mêlé d'histoires de prophètes.", "lieu": "Le récit se passe à Jérusalem, en Israël et en Juda. Le lieu de rédaction est inconnu.", "resume": "Salomon succède à David et construit le Temple à Jérusalem. Après sa mort, le royaume se divise en deux. Le prophète Élie défend la foi en un seul Dieu contre le culte de Baal.", "message": "La fidélité à Dieu compte plus que la puissance des rois.", "personnes": [ { "nom": "Salomon", "qui": "Un roi célèbre pour sa sagesse, qui construit le Temple." }, { "nom": "Élie", "qui": "Un prophète qui défie les prêtres de Baal." }, { "nom": "Jéroboam", "qui": "Le premier roi du royaume du nord." }, { "nom": "Achab et Jézabel", "qui": "Un roi et sa femme qui entraînent le peuple vers Baal." } ], "alire": "Lisez le chapitre 3 sur la sagesse de Salomon et le chapitre 19 sur Élie à l'écoute de Dieu.", "sources": [ "Wikipédia en anglais, article « Books of Kings »", "Wikipédia en français, article « Livres des Rois »" ] },
"2ki": { "auteur": "Selon la tradition juive, le prophète Jérémie en serait l'auteur. Le livre ne le dit pas.", "specialistes": "Les spécialistes pensent que les deux livres des Rois ont été écrits par plusieurs mains, avec une première édition sous le roi Josias et une édition finale au milieu du VIe siècle avant Jésus-Christ.", "date": "Première édition à la fin du VIIe siècle avant Jésus-Christ, édition finale vers le milieu du VIe siècle avant Jésus-Christ. C'est approximatif.", "genre": "Récit historique avec un regard religieux, mêlé d'histoires de prophètes.", "lieu": "Le récit se passe en Israël et en Juda. Le lieu de rédaction est inconnu.", "resume": "Le livre suit les rois d'Israël et de Juda, et le prophète Élisée qui succède à Élie. Le royaume du nord tombe, puis Jérusalem est détruite par Babylone en 586 avant Jésus-Christ.", "message": "L'oubli de Dieu mène à la ruine, mais l'histoire ne se termine pas sur la défaite.", "personnes": [ { "nom": "Élisée", "qui": "Le prophète qui continue la mission d'Élie." }, { "nom": "Ézéchias", "qui": "Un roi de Juda fidèle à Dieu." }, { "nom": "Josias", "qui": "Un roi qui fait une grande réforme religieuse." }, { "nom": "Nabuchodonosor", "qui": "Le roi de Babylone qui détruit Jérusalem." } ], "alire": "Lisez l'histoire de la guérison de Naaman au chapitre 5, puis la fin du livre pour comprendre l'exil.", "sources": [ "Wikipédia en anglais, article « Books of Kings »", "Wikipédia en français, article « Livres des Rois »" ] },
"1ch": { "auteur": "La tradition juive et chrétienne l'attribue à Esdras. Le livre ne donne pas de nom.", "specialistes": "La majorité des spécialistes parlent d'un auteur inconnu appelé « le Chroniqueur », un prêtre lettré de Jérusalem, qui relit les livres plus anciens pour encourager le peuple après l'exil.", "date": "Entre environ 400 et 250 avant Jésus-Christ. C'est approximatif.", "genre": "Généalogies et relecture de l'histoire.", "lieu": "Probablement Jérusalem, d'après l'idée d'un auteur prêtre de cette ville. Ce n'est pas certain.", "resume": "Le livre commence par de longues listes de familles depuis Adam, puis raconte surtout le règne de David. Il insiste sur sa préparation du Temple et du culte.", "message": "Le peuple a des racines, et Dieu rassemble ceux qui reviennent vers lui.", "personnes": [ { "nom": "David", "qui": "Le roi présenté comme un modèle de fidélité." }, { "nom": "Les Lévites", "qui": "Les serviteurs du culte, choisis pour le chant et la musique du Temple." }, { "nom": "Salomon", "qui": "Le fils de David, appelé à construire le Temple." } ], "alire": "Passez vite les listes de noms des chapitres 1 à 9, et lisez le chapitre 16 (le chant de louange de David) et le chapitre 17.", "sources": [ "Wikipédia en anglais, article « Books of Chronicles »", "Wikipédia en français, article « Livres des Chroniques »" ] },
"2ch": { "auteur": "La tradition juive et chrétienne l'attribue à Esdras. Le livre ne donne pas de nom.", "specialistes": "Un auteur inconnu appelé « le Chroniqueur » aurait écrit entre environ 400 et 250 avant Jésus-Christ, en s'appuyant sur des livres plus anciens.", "date": "Entre environ 400 et 250 avant Jésus-Christ. Le dernier événement est l'édit du roi Cyrus en 539 avant Jésus-Christ.", "genre": "Relecture de l'histoire des rois de Juda.", "lieu": "Probablement Jérusalem, mais ce n'est pas certain.", "resume": "Le livre raconte le règne de Salomon, la construction du Temple, puis l'histoire des rois de Juda jusqu'à la chute de Jérusalem. Il se termine par l'édit de Cyrus qui permet le retour d'exil.", "message": "Il est toujours possible de revenir vers Dieu.", "personnes": [ { "nom": "Salomon", "qui": "Il construit et dédicace le Temple." }, { "nom": "Ézéchias", "qui": "Un roi qui rétablit le culte." }, { "nom": "Josias", "qui": "Un roi réformateur." }, { "nom": "Cyrus", "qui": "Le roi de Perse qui permet aux exilés de rentrer." } ], "alire": "Lisez le chapitre 7 sur la prière de Salomon, et les derniers versets du chapitre 36 sur le retour.", "sources": [ "Wikipédia en anglais, article « Books of Chronicles »", "Wikipédia en français, article « Livres des Chroniques »" ] },
"ezr": { "auteur": "La tradition lie Esdras à ce livre. Autrefois Esdras et Néhémie formaient un seul livre.", "specialistes": "Les spécialistes parlent d'un ensemble « Esdras et Néhémie », composé à partir de récits et de documents officiels. Une partie est écrite en araméen, la langue de l'administration.", "date": "Le récit commence en 538 avant Jésus-Christ avec le retour d'exil, et la dédicace du Temple a lieu en 515. La rédaction finale est probablement vers 400 avant Jésus-Christ. C'est approximatif.", "genre": "Récit historique.", "lieu": "Le récit se passe à Babylone et à Jérusalem. Le lieu d'écriture est inconnu.", "resume": "Le roi de Perse Cyrus permet aux exilés de rentrer à Jérusalem, et le Temple est reconstruit. Puis Esdras arrive et ramène le peuple à la loi de Moïse.", "message": "Reconstruire demande de la foi et de la patience.", "personnes": [ { "nom": "Cyrus", "qui": "Le roi de Perse qui autorise le retour." }, { "nom": "Zorobabel", "qui": "Le chef des exilés qui reviennent." }, { "nom": "Esdras", "qui": "Un prêtre et scribe qui enseigne la loi." }, { "nom": "Darius", "qui": "Un roi de Perse sous lequel le Temple est achevé." } ], "alire": "Lisez le chapitre 1 sur le retour et le chapitre 3 sur la pose des fondations du Temple.", "sources": [ "Wikipédia en anglais, article « Book of Ezra »" ] },
"neh": { "auteur": "Selon une tradition rabbinique, Néhémie en serait le vrai auteur. Autrefois le livre était uni à celui d'Esdras.", "specialistes": "Le cœur du livre est probablement un récit personnel de Néhémie. Il aurait été uni à Esdras vers 400 avant Jésus-Christ, puis retouché plus tard.", "date": "Les événements se passent dans la seconde moitié du Ve siècle avant Jésus-Christ. La rédaction est probablement vers 400 avant Jésus-Christ, avec des retouches ensuite.", "genre": "Récit historique à la première personne.", "lieu": "Le récit se passe à Suse, en Perse, puis à Jérusalem.", "resume": "Néhémie, échanson du roi de Perse, obtient la permission d'aller à Jérusalem. Il reconstruit les murs malgré l'opposition des voisins, puis rétablit la vie du peuple autour de la loi.", "message": "Il faut prier et agir ensemble.", "personnes": [ { "nom": "Néhémie", "qui": "Un responsable juif de la cour perse qui devient gouverneur." }, { "nom": "Artaxerxès", "qui": "Le roi de Perse qui l'envoie à Jérusalem." }, { "nom": "Esdras", "qui": "Le scribe qui lit la loi au peuple." } ], "alire": "Lisez les chapitres 1 et 2 pour la prière et le départ, puis le chapitre 8 pour la lecture de la loi.", "sources": [ "Wikipédia en anglais, article « Book of Nehemiah »", "Wikipédia en français, article « Livre de Néhémie »" ] },
"tob": { "auteur": "Le livre ne nomme pas son auteur, et aucune tradition fiable ne le nomme.", "specialistes": "Les spécialistes pensent qu'un auteur juif inconnu l'a écrit dans une langue sémitique, hébreu ou araméen. Des fragments ont été retrouvés parmi les manuscrits de la mer Morte. Le récit contient aussi des erreurs de géographie.", "date": "Au IIIe siècle ou au début du IIe siècle avant Jésus-Christ. C'est approximatif.", "genre": "Récit édifiant, une histoire de famille avec une leçon.", "lieu": "Le récit se passe à Ninive et à Ecbatane. Le lieu d'écriture n'est pas établi. Une origine en Mésopotamie semble logique, mais d'autres lieux sont proposés.", "resume": "Tobit, un juif exilé, devient aveugle. Son fils Tobie part en voyage accompagné de l'ange Raphaël, qui se fait passer pour un guide. Tobie rencontre Sara, la guérit du malheur qui la frappe et rapporte un remède pour son père.", "message": "Dieu écoute la prière et accompagne les familles dans leurs épreuves. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Tobit", "qui": "Un homme juste, exilé à Ninive, qui devient aveugle." }, { "nom": "Tobie", "qui": "Son fils, qui part en voyage." }, { "nom": "Raphaël", "qui": "L'ange qui guide Tobie sans se faire reconnaître." }, { "nom": "Sara", "qui": "Une jeune femme, que Tobie épouse." } ], "alire": "C'est un récit facile et plaisant. Lisez-le comme un conte, du début à la fin.", "sources": [ "Wikipédia en anglais, article « Book of Tobit »", "Wikipédia en français, article « Livre de Tobie »" ] },
"jdt": { "auteur": "Le livre ne nomme pas son auteur. L'auteur était probablement juif.", "specialistes": "Les spécialistes pensent qu'il a été écrit dans une langue sémitique, hébreu ou araméen, puis qu'il nous est arrivé en grec. Beaucoup le lisent comme un récit inspiré, mais pas comme une histoire exacte.", "date": "Généralement placé au IIe siècle avant Jésus-Christ, à l'époque de la révolte des Maccabées. C'est approximatif.", "genre": "Récit de courage, proche d'un roman historique.", "lieu": "Le récit se passe à Béthulie, une ville assiégée. Le lieu d'écriture est inconnu.", "resume": "Une armée assiège la ville de Béthulie. Judith, une veuve, prie puis se rend dans le camp ennemi. Elle réussit à tuer le chef Holopherne, et la ville est sauvée.", "message": "Dieu peut sauver par une personne qui semble faible, et la prière donne du courage. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Judith", "qui": "Une veuve pieuse et courageuse." }, { "nom": "Holopherne", "qui": "Le général ennemi." }, { "nom": "Nabuchodonosor", "qui": "Le roi dont Holopherne conduit l'armée." }, { "nom": "Ozias", "qui": "Un chef de Béthulie." } ], "alire": "Lisez les chapitres 8 à 13, le cœur du récit.", "sources": [ "Wikipédia en anglais, article « Book of Judith »", "Wikipédia en français, article « Livre de Judith »" ] },
"est": { "auteur": "Le livre reste anonyme. Une tradition l'attribue à Mardochée, parce qu'il était bien placé pour connaître les faits.", "specialistes": "Beaucoup de spécialistes voient dans le livre une œuvre de littérature, un récit écrit pour expliquer la fête de Pourim. Les difficultés historiques et les exagérations font penser à un récit en partie imaginé.", "date": "Entre le IVe et le IIe siècle avant Jésus-Christ, selon une datation courante. Le récit se situe au temps du roi perse Assuérus, souvent identifié à Xerxès Ier, qui a régné de 486 à 465 avant Jésus-Christ.", "genre": "Récit, proche du roman historique.", "lieu": "Le récit se passe à Suse, la capitale perse. Le lieu d'écriture est inconnu.", "resume": "Esther, une jeune juive, devient reine de Perse. Elle découvre que Haman, un ministre, veut faire tuer son peuple. Avec l'aide de son cousin Mardochée, elle ose parler au roi et sauve les siens.", "message": "Oser parler peut sauver beaucoup d'autres. La fête de Pourim en garde le souvenir.", "personnes": [ { "nom": "Esther", "qui": "Une jeune juive devenue reine de Perse." }, { "nom": "Mardochée", "qui": "Son cousin, qui l'a élevée." }, { "nom": "Haman", "qui": "Un ministre qui veut détruire les juifs." }, { "nom": "Assuérus", "qui": "Le roi de Perse." } ], "alire": "C'est un récit très vivant, lisez-le d'une traite. Les additions grecques sont dans la Bible catholique.", "sources": [ "Wikipédia en anglais, article « Book of Esther »", "Wikipédia en français, article « Livre d'Esther »" ] },
"1ma": { "auteur": "L'auteur est anonyme et inconnu.", "specialistes": "Il a probablement écrit en hébreu, mais ce texte est perdu, et nous avons le livre en grec. Il écrivait après la réussite de la révolte, dans le royaume asmonéen indépendant.", "date": "Probablement sous le grand prêtre Jean Hyrcan (134 à 104 avant Jésus-Christ). Quelques spécialistes pensent au début du règne d'Alexandre Jannée, vers 103 avant Jésus-Christ.", "genre": "Récit historique.", "lieu": "Probablement en Judée. Le texte se concentre sur Jérusalem.", "resume": "Le roi grec Antiochus IV interdit les pratiques juives. Mattathias et ses fils, dont Judas Maccabée, se révoltent. Le livre raconte la reprise de Jérusalem en 164 avant Jésus-Christ et la purification du Temple.", "message": "Rester fidèle à sa foi, même quand c'est risqué. La fête de Hanoucca vient de ces événements. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Antiochus IV", "qui": "Le roi grec qui persécute les juifs." }, { "nom": "Mattathias", "qui": "Le prêtre qui lance la révolte." }, { "nom": "Judas Maccabée", "qui": "Son fils, chef de l'armée qui reprend Jérusalem." }, { "nom": "Jonathan et Simon", "qui": "Les frères de Judas qui continuent la lutte." } ], "alire": "Lisez le chapitre 1 et 2 pour le début de la révolte, puis le chapitre 4 sur la purification du Temple.", "sources": [ "Wikipédia en anglais, article « 1 Maccabees »" ] },
"2ma": { "auteur": "L'auteur n'est pas connu. Il dit résumer une œuvre en cinq volumes de Jason de Cyrène, qui n'existe plus.", "specialistes": "Il a écrit en grec et était probablement un juif d'Égypte, peut-être à Alexandrie, pour d'autres juifs vivant hors de Judée. Ce livre n'est pas la suite du premier livre, c'est un autre récit de la même révolte.", "date": "Probablement entre 150 et 100 avant Jésus-Christ.", "genre": "Récit historique, avec une forte part d'enseignement religieux.", "lieu": "Probablement Alexandrie, en Égypte.", "resume": "Le livre raconte la persécution d'Antiochus IV et la révolte de Judas Maccabée, jusqu'à la défaite de Nicanor en 161 avant Jésus-Christ. Il montre des martyrs qui espèrent la résurrection.", "message": "Dieu est plus fort que les persécuteurs, et la mort n'a pas le dernier mot. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Judas Maccabée", "qui": "Le chef de la révolte." }, { "nom": "Antiochus IV", "qui": "Le roi qui persécute." }, { "nom": "Les sept frères et leur mère", "qui": "Des martyrs qui refusent de renier leur foi." }, { "nom": "Nicanor", "qui": "Un général vaincu par Judas." } ], "alire": "Lisez le chapitre 7, l'histoire de la mère et de ses sept fils.", "sources": [ "Wikipédia en anglais, article « 2 Maccabees »" ] },
"job": { "auteur": "Le livre est écrit par un auteur anonyme, presque certainement un Israélite.", "specialistes": "Les spécialistes pensent qu'un poète a repris une vieille légende et en a fait une grande œuvre. La langue du livre mêle de l'hébreu tardif et de l'araméen.", "date": "Probablement à l'époque perse, entre 540 et 330 avant Jésus-Christ. C'est approximatif.", "genre": "Sagesse et poème, avec un récit au début et à la fin.", "lieu": "Le récit se passe au pays d'Uz, au sud d'Édom ou dans le nord de l'Arabie. Le lieu d'écriture est inconnu.", "resume": "Job est un homme juste et heureux. Il perd tout, ses enfants, ses biens, sa santé. Ses amis cherchent des explications, Job interroge Dieu, et Dieu lui répond.", "message": "Le livre ne donne pas une explication simple à la souffrance. Il montre qu'on peut crier vers Dieu avec honnêteté.", "personnes": [ { "nom": "Job", "qui": "Un homme juste qui souffre sans comprendre." }, { "nom": "Les trois amis de Job", "qui": "Ils croient que Job a dû commettre une faute." }, { "nom": "Dieu", "qui": "Il répond à Job depuis la tempête." } ], "alire": "Lisez les chapitres 1 et 2, puis les chapitres 38 à 42. Les discours du milieu sont longs.", "sources": [ "Wikipédia en anglais, article « Book of Job »" ] },
"psa": { "auteur": "La tradition attribue les psaumes au roi David, mais les titres citent aussi les fils de Coré, Asaph, Salomon et Moïse.", "specialistes": "Les spécialistes ne considèrent pas David comme l'auteur de tous les psaumes. Ces noms servent à rattacher les prières à des figures connues. Le recueil s'est formé peu à peu.", "date": "La datation est « notoirement difficile ». Certains psaumes sont d'avant l'exil, d'autres d'après. Le recueil a été fixé progressivement.", "genre": "Prières chantées et poésie.", "lieu": "Un lieu précis n'est pas établi pour l'ensemble du recueil.", "resume": "Le livre rassemble 150 psaumes, des prières et des chants. On y trouve la louange, la plainte, la demande de pardon, la reconnaissance et la confiance. Le recueil est divisé en cinq parties.", "message": "On peut tout dire à Dieu, la joie comme la colère.", "personnes": [ { "nom": "David", "qui": "Le roi à qui beaucoup de psaumes sont attribués." }, { "nom": "Asaph", "qui": "Un chantre à qui plusieurs psaumes sont attribués." }, { "nom": "Les fils de Coré", "qui": "Une famille de chantres du Temple." }, { "nom": "Moïse", "qui": "Le psaume 90 lui est attribué." } ], "alire": "Commencez par le psaume 23, puis les psaumes 1, 8, 51 et 139.", "sources": [ "Wikipédia en anglais, article « Psalms »", "Wikipédia en français, article « Livre des Psaumes »" ] },
"pro": { "auteur": "La tradition attribue le livre au roi Salomon et à ses élèves.", "specialistes": "Les spécialistes y voient un recueil de recueils, formé à des époques différentes. Les chapitres 1 à 9 seraient parmi les derniers écrits.", "date": "Plusieurs époques. La forme finale date de l'époque perse ou grecque, selon plusieurs spécialistes. C'est approximatif.", "genre": "Sagesse, avec des proverbes et de courts poèmes.", "lieu": "Le lieu d'écriture est inconnu. Les titres évoquent la cour de Jérusalem et le roi Ézéchias.", "resume": "Le livre rassemble des proverbes et des conseils de sagesse. Il parle du travail, de la parole, de l'amitié et de la famille. Le premier chapitre présente la sagesse comme une invitée qui appelle.", "message": "La sagesse commence par le respect de Dieu.", "personnes": [ { "nom": "Salomon", "qui": "Le roi sage à qui le livre est attribué." }, { "nom": "La Sagesse", "qui": "Une figure qui appelle à bien vivre, dans les chapitres 1 à 9." }, { "nom": "Ézéchias", "qui": "Un roi dont les serviteurs ont copié d'autres proverbes." } ], "alire": "Lisez quelques proverbes par jour. Le chapitre 8 et le chapitre 31 sont de beaux points d'entrée.", "sources": [ "Wikipédia en anglais, article « Book of Proverbs »" ] },
"ecc": { "auteur": "La tradition rabbinique l'attribue à Salomon âgé. Le livre signe « Qohélet, fils de David, roi à Jérusalem ».", "specialistes": "Les spécialistes pensent que Salomon n'est pas l'auteur. Le vocabulaire (mots perses et araméens) indique une date bien plus tardive.", "date": "Pas avant 450 environ et au plus tard vers 180 avant Jésus-Christ. Les spécialistes discutent s'il vient de l'époque perse ou grecque.", "genre": "Réflexion de sagesse.", "lieu": "Probablement Jérusalem, d'après la présentation du livre. Ce n'est pas certain.", "resume": "Qohélet regarde la vie avec honnêteté. Il constate que beaucoup de choses sont éphémères, appelées « vanité ». Il invite pourtant à goûter les petits bonheurs de la vie.", "message": "Tout passe, mais il y a un temps pour chaque chose, et la vie est un don.", "personnes": [ { "nom": "Qohélet", "qui": "Le sage qui parle dans le livre, présenté comme un fils de David." }, { "nom": "Salomon", "qui": "Le roi à qui la tradition attribue ce livre." } ], "alire": "Lisez le chapitre 3, « Il y a un temps pour tout », et le chapitre 12.", "sources": [ "Wikipédia en anglais, article « Ecclesiastes »" ] },
"sol": { "auteur": "Le titre dit « de Salomon », et la tradition le lui attribue.", "specialistes": "La majorité des spécialistes pensent qu'il a été écrit bien après Salomon, d'après la langue. Ils y voient surtout de la poésie d'amour humaine.", "date": "Souvent daté du IIIe siècle avant Jésus-Christ. C'est approximatif et discuté.", "genre": "Poème d'amour.", "lieu": "Le lieu d'écriture est inconnu.", "resume": "Deux amoureux se parlent et se cherchent à travers des images de nature, de jardins et de vignes. Les juifs y lisent l'amour de Dieu pour Israël, les chrétiens l'amour du Christ pour l'Église.", "message": "L'amour est un don fort et beau, et il peut parler de Dieu.", "personnes": [ { "nom": "La bien-aimée", "qui": "La jeune femme qui parle et cherche son aimé." }, { "nom": "Le bien-aimé", "qui": "Le jeune homme dont elle parle." }, { "nom": "Les filles de Jérusalem", "qui": "Un chœur qui écoute les amoureux." } ], "alire": "Lisez-le à voix haute, comme un poème, en commençant par le chapitre 2.", "sources": [ "Wikipédia en anglais, article « Song of Songs »" ] },
"wis": { "auteur": "Le livre porte le nom de Salomon, mais il a été écrit en grec par un auteur juif inconnu d'Alexandrie.", "specialistes": "Il y a un consensus parmi les spécialistes pour dire qu'il a été écrit en grec, à Alexandrie, autour du début de notre ère.", "date": "Surtout daté du Ier siècle avant Jésus-Christ, parfois autour du début du Ier siècle après. C'est approximatif.", "genre": "Sagesse et réflexion religieuse.", "lieu": "Alexandrie, en Égypte.", "resume": "Le livre encourage les juifs qui vivent en Égypte parmi des Grecs. Il célèbre la sagesse de Dieu, parle du sort des justes et de la vie après la mort, puis relit l'histoire de l'Exode.", "message": "Les justes sont dans la main de Dieu, et la sagesse vient de lui. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Salomon", "qui": "Le roi dont le nom sert de signature." }, { "nom": "La Sagesse", "qui": "Une figure qui guide l'être humain vers Dieu." }, { "nom": "Les justes", "qui": "Ceux qui restent fidèles à Dieu." } ], "alire": "Lisez le chapitre 3, « Les âmes des justes sont dans la main de Dieu », et le chapitre 7 sur la sagesse.", "sources": [ "Wikipédia en anglais, article « Book of Wisdom »" ] },
"sir": { "auteur": "Jésus ben Sira, un lettré de Jérusalem. C'est un des rares auteurs bibliques à avoir signé son livre.", "specialistes": "Les spécialistes s'accordent sur l'auteur et sur l'époque. Son petit-fils l'a traduit en grec et a ajouté un prologue.", "date": "Écrit entre 196 et 175 avant Jésus-Christ environ, vers 180. La traduction grecque date d'environ 117 avant Jésus-Christ.", "genre": "Sagesse, avec de nombreux conseils.", "lieu": "Jérusalem, pour l'original. La traduction a été faite en Égypte.", "resume": "Le livre rassemble des conseils pour la vie quotidienne, l'amitié, la famille, le travail et la prière. Il fait aussi l'éloge de grands personnages de l'histoire d'Israël.", "message": "La sagesse se reçoit de Dieu et se vit au quotidien. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Jésus ben Sira", "qui": "L'auteur, un sage de Jérusalem." }, { "nom": "Le petit-fils de Ben Sira", "qui": "Le traducteur du livre en grec." }, { "nom": "Les grands hommes d'Israël", "qui": "Une longue liste de personnages loués à la fin du livre." } ], "alire": "Lisez le chapitre 6 sur l'amitié et le chapitre 38 sur le travail et la maladie.", "sources": [ "Wikipédia en anglais, article « Sirach »" ] },
"isa": { "auteur": "Le livre se présente comme les paroles du prophète Isaïe, qui a vécu au VIIIe siècle avant Jésus-Christ.", "specialistes": "La grande majorité des spécialistes pensent que le livre a plusieurs auteurs. Les chapitres 1 à 39 viennent surtout d'Isaïe, les chapitres 40 à 55 d'un prophète anonyme pendant l'exil, et les chapitres 56 à 66 d'une époque encore plus tardive.", "date": "Du VIIIe siècle avant Jésus-Christ pour la première partie, jusqu'après le retour d'exil (après 539 avant Jésus-Christ) pour la suite. C'est approximatif.", "genre": "Prophétie et poésie.", "lieu": "Jérusalem pour la première partie. L'exil à Babylone pour la deuxième.", "resume": "Isaïe appelle à la justice et annonce le jugement. Puis il console le peuple en exil et annonce un retour. Le livre contient de grands textes sur un roi sauveur et sur un serviteur qui souffre.", "message": "Dieu console et sauve son peuple. Les chrétiens y reconnaissent beaucoup de passages qui annoncent Jésus.", "personnes": [ { "nom": "Isaïe", "qui": "Le prophète de Jérusalem, appelé à parler de la part de Dieu." }, { "nom": "Ézéchias", "qui": "Un roi de Juda, menacé par l'armée assyrienne." }, { "nom": "Cyrus", "qui": "Le roi de Perse que Dieu utilise pour libérer les exilés." }, { "nom": "Le serviteur de Dieu", "qui": "Une figure mystérieuse qui souffre pour les autres, que les chrétiens rapprochent de Jésus." } ], "alire": "Lisez le chapitre 6 (l'appel d'Isaïe), le chapitre 11 et le chapitre 53. Pour la consolation, lisez le chapitre 40.", "sources": [ "Wikipédia en anglais, article « Book of Isaiah »", "Wikipédia en français, article « Livre d'Isaïe »" ] },
"jer": { "auteur": "Le livre se présente comme « les paroles de Jérémie, fils de Hilkiya ». Son secrétaire Baruch l'aide à écrire.", "specialistes": "Les spécialistes pensent que le livre a été très retravaillé par des disciples. Les poèmes des chapitres 1 à 25 sont probablement les plus proches du prophète lui-même.", "date": "Jérémie parle de 627 à 586 avant Jésus-Christ environ. La forme finale du livre est plus tardive, entre l'époque perse et le IIe siècle avant Jésus-Christ selon les versions. C'est approximatif.", "genre": "Prophétie, poésie et récit.", "lieu": "Jérusalem, avant la chute de la ville, puis ses environs. Le lieu de rédaction finale est inconnu.", "resume": "Jérémie annonce le malheur qui vient, car le peuple s'est éloigné de Dieu. Il souffre d'être rejeté. Il annonce aussi une alliance nouvelle et un avenir d'espérance.", "message": "Dieu reste fidèle et promet une alliance nouvelle.", "personnes": [ { "nom": "Jérémie", "qui": "Le prophète qui annonce la chute de Jérusalem." }, { "nom": "Baruch", "qui": "Son secrétaire." }, { "nom": "Josias", "qui": "Le roi réformateur du début du ministère de Jérémie." }, { "nom": "Nabuchodonosor", "qui": "Le roi de Babylone qui détruit Jérusalem." } ], "alire": "Lisez le chapitre 1 sur l'appel, le chapitre 18 sur le potier, et le chapitre 31 sur l'alliance nouvelle.", "sources": [ "Wikipédia en anglais, article « Book of Jeremiah »" ] },
"lam": { "auteur": "La tradition attribue les Lamentations au prophète Jérémie.", "specialistes": "Le consensus des spécialistes est que Jérémie n'en est pas l'auteur. Le livre est un ensemble de cinq poèmes, de style semblable aux plaintes sur les villes détruites.", "date": "Après la destruction de Jérusalem en 586 avant Jésus-Christ. La date précise est inconnue.", "genre": "Poèmes de deuil.", "lieu": "Probablement Juda, mais le lieu exact est inconnu.", "resume": "Cinq poèmes pleurent la ville de Jérusalem détruite. Ils parlent de la faim, de la honte et du deuil. Dieu ne répond pas, mais le peuple lui parle encore. Le chapitre 3 laisse place à l'espérance.", "message": "On peut pleurer devant Dieu, et même au cœur de la nuit l'espérance reste possible.", "personnes": [ { "nom": "Jérusalem", "qui": "La ville, représentée comme une veuve en pleurs." }, { "nom": "Le peuple de Juda", "qui": "Ceux qui ont perdu leur ville." }, { "nom": "Jérémie", "qui": "Le prophète auquel la tradition attribue le livre." } ], "alire": "Lisez le chapitre 3, surtout le passage sur la fidélité de Dieu qui se renouvelle chaque matin.", "sources": [ "Wikipédia en anglais, article « Book of Lamentations »" ] },
"bar": { "auteur": "Le livre porte le nom de Baruch, le secrétaire du prophète Jérémie. La tradition l'a longtemps considéré comme l'auteur.", "specialistes": "Les spécialistes sont d'accord pour dire que ni Baruch ni Jérémie ne l'ont écrit. Le livre est composé de plusieurs parties, d'époques différentes.", "date": "Discutée. Selon les spécialistes, entre 300 avant Jésus-Christ et 70 après. Une introduction de la Bible œcuménique propose la seconde moitié du IIe siècle avant Jésus-Christ.", "genre": "Prière, poème et exhortation.", "lieu": "Le récit se situe à Babylone, parmi les exilés. Le lieu d'écriture est inconnu.", "resume": "Baruch lit son livre aux exilés. Ils confessent leurs fautes et prient. Le livre loue la sagesse, qui est la loi de Dieu, et annonce la consolation de Jérusalem.", "message": "Revenir à Dieu, c'est retrouver la sagesse. Ce livre est reconnu par les catholiques et les orthodoxes.", "personnes": [ { "nom": "Baruch", "qui": "Le secrétaire de Jérémie, présenté comme le narrateur." }, { "nom": "Les exilés", "qui": "Ceux qui prient à Babylone." }, { "nom": "Jérusalem", "qui": "La ville personnifiée, qui console ses enfants." } ], "alire": "Lisez le chapitre 3 sur la sagesse, puis le chapitre 5 qui annonce la joie du retour.", "sources": [ "Wikipédia en anglais, article « Book of Baruch »", "Wikipédia en français, article « Livre de Baruch »" ] },
"eze": { "auteur": "Le livre se présente comme les paroles du prophète Ézéchiel, fils de Buzi, prêtre en exil à Babylone. Selon une tradition juive, la Grande Assemblée l'aurait écrit à partir de ses paroles.", "specialistes": "La plupart des spécialistes acceptent que le cœur du livre vienne vraiment du prophète. Ils voient aussi des ajouts faits plus tard par ses disciples.", "date": "Les visions sont datées de 593 à 571 avant Jésus-Christ. La rédaction finale est un peu plus tardive.", "genre": "Prophétie avec des visions et des gestes symboliques.", "lieu": "Babylone, chez les exilés.", "resume": "Ézéchiel est déporté à Babylone. Il voit la gloire de Dieu, annonce la chute de Jérusalem, puis parle d'espérance. Il décrit un peuple ramené à la vie et un temple nouveau.", "message": "Dieu est avec son peuple même en exil, et il donne un cœur nouveau.", "personnes": [ { "nom": "Ézéchiel", "qui": "Un prêtre devenu prophète en exil." }, { "nom": "Les exilés", "qui": "Les juifs déportés à Babylone." }, { "nom": "Dieu", "qui": "Il apparaît à Ézéchiel dans des visions." } ], "alire": "Lisez le chapitre 37 sur les ossements desséchés qui reprennent vie, et le chapitre 36 sur le cœur nouveau.", "sources": [ "Wikipédia en anglais, article « Book of Ezekiel »" ] },
"dan": { "auteur": "Le livre se présente comme l'histoire de Daniel, un juif exilé à Babylone. L'auteur réel est inconnu.", "specialistes": "La majorité des spécialistes pensent qu'il a été écrit au IIe siècle avant Jésus-Christ, lors de la persécution d'Antiochus IV. Il se situe au VIe siècle pour encourager les croyants.", "date": "Au IIe siècle avant Jésus-Christ, vers 167 à 164 pour les visions. C'est la datation la plus courante, mais certains la contestent.", "genre": "Récits de cour et visions apocalyptiques, pleines de symboles.", "lieu": "Le récit se passe à Babylone. Le lieu d'écriture est inconnu, probablement en Judée.", "resume": "Daniel et ses amis restent fidèles à Dieu dans un pays étranger. Ils sont sauvés de la fournaise et de la fosse aux lions. La seconde partie contient des visions sur la fin des royaumes. La version catholique ajoute Suzanne et Bel.", "message": "Dieu reste maître de l'histoire, même quand le mal semble gagner.", "personnes": [ { "nom": "Daniel", "qui": "Un jeune juif sage, conseiller des rois." }, { "nom": "Les trois amis de Daniel", "qui": "Sidrac, Misac et Abdénago, jetés dans la fournaise." }, { "nom": "Nabuchodonosor", "qui": "Le roi de Babylone." }, { "nom": "Suzanne", "qui": "Une femme innocente sauvée par Daniel." } ], "alire": "Lisez les chapitres 3 et 6, puis le chapitre 13 sur Suzanne. Les visions des chapitres 7 à 12 sont difficiles.", "sources": [ "Wikipédia en anglais, article « Book of Daniel »" ] },
"hos": { "auteur": "Le livre se présente comme les paroles du prophète Osée.", "specialistes": "Beaucoup de spécialistes pensent que l'essentiel est du VIIIe siècle avant Jésus-Christ, mais que des éditeurs ont retravaillé le livre plus tard.", "date": "Surtout du temps de Jéroboam II, roi d'Israël vers 793 à 753 avant Jésus-Christ. La date est approximative.", "genre": "Prophétie et poésie.", "lieu": "Le royaume du nord, Israël.", "resume": "Osée vit une histoire de mariage avec une femme infidèle. Elle sert d'image pour l'amour de Dieu pour Israël. Le peuple s'est tourné vers d'autres dieux, mais Dieu l'appelle à revenir.", "message": "Dieu aime d'un amour qui ne se lasse pas.", "personnes": [ { "nom": "Osée", "qui": "Le prophète du royaume du nord." }, { "nom": "Gomer", "qui": "Sa femme, image du peuple infidèle." }, { "nom": "Jéroboam II", "qui": "Un roi d'Israël de l'époque d'Osée." } ], "alire": "Lisez le chapitre 2 et le chapitre 11, la tendresse de Dieu comme un père.", "sources": [ "Wikipédia en anglais, article « Book of Hosea »" ] },
"joe": { "auteur": "Le livre se présente comme les paroles du prophète Joël. Aucun détail personnel n'est donné.", "specialistes": "Aucun personnage ou événement daté n'est cité. Les spécialistes proposent des dates très différentes.", "date": "Du IXe siècle avant Jésus-Christ jusqu'à environ 350 avant Jésus-Christ. Beaucoup penchent pour la période perse. Ces dates sont très incertaines.", "genre": "Prophétie.", "lieu": "Juda et Jérusalem.", "resume": "Une invasion de sauterelles ravage le pays. Joël appelle à revenir à Dieu avec tout son cœur. Il annonce que l'Esprit sera répandu sur tous.", "message": "Il est toujours temps de revenir à Dieu, et l'Esprit est promis à tous.", "personnes": [ { "nom": "Joël", "qui": "Le prophète." }, { "nom": "Le peuple de Juda", "qui": "Appelé à jeûner et à revenir à Dieu." }, { "nom": "Les prêtres", "qui": "Appelés à prier pour le peuple." } ], "alire": "Lisez le chapitre 2, surtout le passage sur l'Esprit répandu sur tous.", "sources": [ "Wikipédia en anglais, article « Book of Joel »" ] },
"amo": { "auteur": "Le livre se présente comme les paroles d'Amos, un berger de Tékoa, en Juda.", "specialistes": "Les spécialistes datent le prophète du VIIIe siècle avant Jésus-Christ. Les qualités littéraires du livre font penser à un homme instruit.", "date": "Vers 750 avant Jésus-Christ, au temps du roi Jéroboam II. C'est approximatif.", "genre": "Prophétie.", "lieu": "Il vit à Tékoa, en Juda, mais prophétise dans le royaume du nord.", "resume": "Amos dénonce l'injustice envers les pauvres et un culte sans cœur. Il annonce le jugement. Il finit par une promesse de relèvement.", "message": "Dieu n'accepte pas qu'on prie en méprisant les pauvres.", "personnes": [ { "nom": "Amos", "qui": "Un berger devenu prophète." }, { "nom": "Jéroboam II", "qui": "Le roi d'Israël." }, { "nom": "Ozias", "qui": "Le roi de Juda." } ], "alire": "Lisez le chapitre 5, qui parle de justice et de droit.", "sources": [ "Wikipédia en anglais, article « Book of Amos »" ] },
"oba": { "auteur": "Le livre est attribué au prophète Abdias. On ne sait rien d'autre de lui.", "specialistes": "La majorité des spécialistes situent le livre peu après la chute de Jérusalem en 587. D'autres y voient un livre formé peu à peu aux Ve et IVe siècles.", "date": "Peu après 587 avant Jésus-Christ, selon la majorité. C'est approximatif.", "genre": "Prophétie, un seul chapitre.", "lieu": "Juda, avec Édom pour cible.", "resume": "Abdias annonce la chute d'Édom, un voisin de Juda descendant d'Ésaü. Édom est devenu orgueilleux et violent envers son frère Jacob. Le livre se termine par l'espérance.", "message": "L'orgueil finit toujours par tomber, et Dieu rend justice.", "personnes": [ { "nom": "Abdias", "qui": "Le prophète." }, { "nom": "Édom", "qui": "Un peuple voisin, descendant d'Ésaü." }, { "nom": "Jacob", "qui": "Désigne le peuple d'Israël." } ], "alire": "C'est le plus court livre de l'Ancien Testament, avec 21 versets. Lisez-le en entier en quelques minutes.", "sources": [ "Wikipédia en anglais, article « Book of Obadiah »" ] },
"jon": { "auteur": "Le livre ne nomme pas son auteur. Il parle d'un prophète nommé Jonas, fils d'Amittaï.", "specialistes": "La plupart des spécialistes y voient un récit imaginé, parfois humoristique, écrit longtemps après l'époque où l'histoire se situe. Le vocabulaire est celui de l'araméen d'après l'exil.", "date": "Après l'exil. Le livre mentionne le temps du roi Jéroboam II, mais il a été écrit plus tard. C'est approximatif.", "genre": "Récit symbolique, avec un psaume au milieu.", "lieu": "Le récit se passe en mer et à Ninive. Le lieu d'écriture est inconnu.", "resume": "Dieu envoie Jonas à Ninive pour appeler la ville à changer de vie. Jonas s'enfuit en bateau et un grand poisson l'avale. Il finit par obéir, la ville se repent, et Jonas se fâche de voir Dieu pardonner.", "message": "La miséricorde de Dieu s'étend à tous, même aux ennemis.", "personnes": [ { "nom": "Jonas", "qui": "Un prophète qui refuse sa mission." }, { "nom": "Les habitants de Ninive", "qui": "Une ville ennemie qui se repent." }, { "nom": "Les marins", "qui": "Des hommes qui découvrent le Dieu de Jonas." } ], "alire": "Le livre est court, 4 chapitres. Lisez-le d'une traite.", "sources": [ "Wikipédia en anglais, article « Book of Jonah »" ] },
"mic": { "auteur": "Le livre se présente comme les paroles de Michée de Moréshet, un village de Juda.", "specialistes": "Seuls les chapitres 1 à 3 seraient du prophète du VIIIe siècle selon certains. Le reste a été ajouté plus tard, jusqu'à la fin de l'exil.", "date": "Le prophète vit entre 750 et 700 avant Jésus-Christ environ. Le livre est terminé au début du Ve siècle avant Jésus-Christ, selon des spécialistes. C'est approximatif.", "genre": "Prophétie.", "lieu": "Juda, au village de Moréshet. Le lieu d'écriture final est inconnu.", "resume": "Michée dénonce ceux qui prennent les terres des pauvres. Il annonce la chute de Jérusalem. Il parle aussi d'un chef qui naîtra à Bethléem et d'un Dieu qui pardonne.", "message": "Pratiquer la justice, aimer la bonté et marcher humblement avec Dieu.", "personnes": [ { "nom": "Michée", "qui": "Le prophète de Moréshet." }, { "nom": "Ézéchias", "qui": "Le roi de Juda à son époque." }, { "nom": "Un chef de Bethléem", "qui": "Annoncé au chapitre 5." } ], "alire": "Lisez le chapitre 6, surtout le passage sur ce que Dieu demande, et le chapitre 5 sur Bethléem.", "sources": [ "Wikipédia en anglais, article « Book of Micah »" ] },
"nah": { "auteur": "Le livre est attribué au prophète Nahum, de la ville d'Elqosh.", "specialistes": "Le contexte exact est discuté. Beaucoup de spécialistes le placent avant la chute de Ninive en 612.", "date": "Entre 663 et 612 avant Jésus-Christ. D'autres proposent plus tard. C'est approximatif.", "genre": "Prophétie poétique.", "lieu": "Le prophète vient d'Elqosh, dont l'emplacement est discuté. Le lieu d'écriture est inconnu.", "resume": "Nahum annonce la chute de Ninive, la capitale de l'Assyrie, un empire cruel. Pour ceux qui ont été opprimés, c'est une bonne nouvelle.", "message": "Dieu finit par arrêter l'injustice.", "personnes": [ { "nom": "Nahum", "qui": "Le prophète dont le nom veut dire « consolation »." }, { "nom": "Ninive", "qui": "La capitale de l'Assyrie." }, { "nom": "Les Assyriens", "qui": "Un peuple puissant et cruel." } ], "alire": "Le livre est très court. Lisez le chapitre 1, où Dieu est présenté comme un refuge.", "sources": [ "Wikipédia en anglais, article « Book of Nahum »" ] },
"hab": { "auteur": "Le livre est attribué au prophète Habacuc. On ne sait presque rien de lui.", "specialistes": "Les spécialistes pensent qu'il a été écrit entre le milieu et la fin du VIIe siècle avant Jésus-Christ, quand Babylone devenait puissante. Le chapitre 3 est un chant.", "date": "Entre le milieu et la fin du VIIe siècle avant Jésus-Christ. C'est approximatif.", "genre": "Prophétie sous forme de dialogue avec Dieu, et chant.", "lieu": "Juda. Le lieu d'écriture est inconnu.", "resume": "Habacuc demande à Dieu pourquoi le mal gagne. Dieu répond qu'il agira. Le livre se termine par une prière de confiance, même sans récolte.", "message": "Le juste vivra par sa fidélité. Cette phrase est reprise par Paul dans la lettre aux Romains.", "personnes": [ { "nom": "Habacuc", "qui": "Le prophète qui interroge Dieu." }, { "nom": "Les Babyloniens", "qui": "Un peuple en train de grandir en puissance." }, { "nom": "Dieu", "qui": "Il répond à ses questions." } ], "alire": "Lisez les chapitres 1 et 2, puis la prière du chapitre 3.", "sources": [ "Wikipédia en anglais, article « Book of Habakkuk »" ] },
"zep": { "auteur": "Le livre se présente comme les paroles de Sophonie, un descendant d'Ézéchias.", "specialistes": "On ne sait rien de Sophonie en dehors du livre. Beaucoup pensent à l'époque de Josias, mais le livre a pu être complété plus tard.", "date": "Probablement sous le roi Josias (640 à 609 avant Jésus-Christ). D'autres pensent à des ajouts plus tardifs.", "genre": "Prophétie.", "lieu": "Juda et Jérusalem.", "resume": "Sophonie annonce le jour du Seigneur, un jour de jugement. Il parle des humbles qui seront protégés. Le livre finit par un chant de joie.", "message": "Dieu se réjouit au milieu de son peuple.", "personnes": [ { "nom": "Sophonie", "qui": "Le prophète." }, { "nom": "Josias", "qui": "Le roi de son époque." }, { "nom": "Les humbles", "qui": "Ceux que Dieu protège." } ], "alire": "Lisez le chapitre 3, surtout la fin sur la joie de Dieu.", "sources": [ "Wikipédia en anglais, article « Book of Zephaniah »" ] },
"hag": { "auteur": "Le livre est attribué au prophète Aggée.", "specialistes": "Le texte vient probablement du temps d'Aggée lui-même, ou d'une génération plus tard.", "date": "Les faits sont de l'an 520 avant Jésus-Christ. Le texte est achevé vers 515, selon une opinion courante.", "genre": "Prophétie, très court.", "lieu": "Jérusalem, après le retour d'exil.", "resume": "Les exilés sont revenus, mais le Temple est resté en ruines. Aggée les encourage à le reconstruire. Il promet que la gloire du nouveau Temple sera grande.", "message": "Remettre Dieu à la première place.", "personnes": [ { "nom": "Aggée", "qui": "Le prophète." }, { "nom": "Zorobabel", "qui": "Le gouverneur de Juda." }, { "nom": "Josué", "qui": "Le grand prêtre." } ], "alire": "Le livre compte 2 chapitres. Lisez-le en entier.", "sources": [ "Wikipédia en anglais, article « Book of Haggai »" ] },
"zec": { "auteur": "Le livre est attribué au prophète Zacharie.", "specialistes": "La plupart des spécialistes y voient au moins deux auteurs. Les chapitres 1 à 8 viennent de Zacharie, et les chapitres 9 à 14 sont plus tardifs.", "date": "Chapitres 1 à 8 au VIe siècle avant Jésus-Christ, sous le roi Darius. Chapitres 9 à 14 plus tard, probablement au Ve siècle. C'est approximatif.", "genre": "Visions et prophétie, avec des textes apocalyptiques.", "lieu": "Jérusalem, après le retour d'exil.", "resume": "Zacharie encourage la reconstruction du Temple avec des visions pleines d'images. Les chapitres suivants annoncent un roi humble et un jour où Dieu agira.", "message": "Dieu revient habiter parmi son peuple, et il annonce un roi humble.", "personnes": [ { "nom": "Zacharie", "qui": "Le prophète." }, { "nom": "Zorobabel", "qui": "Le gouverneur chargé de reconstruire." }, { "nom": "Josué", "qui": "Le grand prêtre." }, { "nom": "Darius", "qui": "Le roi de Perse de l'époque." } ], "alire": "Lisez le chapitre 9, avec le roi humble sur un ânon, puis le chapitre 2 sur la joie de Jérusalem.", "sources": [ "Wikipédia en anglais, article « Book of Zechariah »" ] },
"mal": { "auteur": "Le livre porte le nom de Malachie. Ce mot veut dire « mon messager », donc ce n'est peut-être pas un vrai nom. Selon le Talmud, Esdras serait l'auteur.", "specialistes": "Les spécialistes pensent que le livre est formé en plusieurs étapes. L'essentiel vient de l'époque perse.", "date": "Les parties les plus anciennes datent d'environ 500 avant Jésus-Christ, avec des retouches à l'époque grecque. C'est approximatif.", "genre": "Prophétie sous forme de dialogues.", "lieu": "Juda et Jérusalem, après l'exil.", "resume": "Le peuple est découragé et le culte se relâche. Malachie leur reproche leur tiédeur. Il annonce l'envoi d'un messager qui prépare la venue du Seigneur.", "message": "Dieu invite à revenir à une vie droite, et il promet de venir.", "personnes": [ { "nom": "Malachie", "qui": "Le prophète, dont le nom veut dire « mon messager »." }, { "nom": "Les prêtres", "qui": "Ceux qui négligent le culte." }, { "nom": "Le peuple de Juda", "qui": "Découragé après le retour d'exil." } ], "alire": "Lisez le chapitre 3, avec l'annonce du messager. Il est court.", "sources": [ "Wikipédia en anglais, article « Book of Malachi »" ] }
};
